#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<string> grid(n);
    for (string& row : grid) {
        cin >> row;
    }

    int count = 0;
    const int di[] = {-1, 1, 0, 0};
    const int dj[] = {0, 0, -1, 1};

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] != 'W') continue;

            for (int d = 0; d < 4; ++d) {
                int ni = i + di[d];
                int nj = j + dj[d];

                if (ni >= 0 && ni < n && nj >= 0 && nj < m &&
                    grid[ni][nj] == 'P') {
                    ++count;
                    grid[ni][nj] = '.';
                    break;
                }
            }
        }
    }

    cout << count << '\n';
    return 0;
}

